import { BasePolicy } from '@adonisjs/bouncer'
import type User from '#models/user'

/**
 * Generated by `node ace make:admin-resource Tag --policy`, then
 * narrowed: tags are for admins only. Staff edit products but can't
 * list tags, so a product's tags are read-only for them (FR-09), as its
 * category is (FR-08).
 */
export default class TagPolicy extends BasePolicy {
  viewList(user: User) {
    return user.role === 'admin'
  }

  view(user: User) {
    return user.role === 'admin'
  }

  create(user: User) {
    return user.role === 'admin'
  }

  update(user: User) {
    return user.role === 'admin'
  }
}
